  "向访客共享会话，让其通过浏览器实时查看并发送经你批准的消息。使用访客链接需要登录 T3 Connect。":
    "브라우저에서 라이브를보고 동의하는 메시지를 보내는 손님과 대화를 공유합니다. T3 Connect에 로그인하여 손님 링크를 사용하십시오.",
  "Claude 或 Codex 完成一轮后，在空输入框中预测下一条消息，按 Tab 使用。每次建议会额外消耗套餐中的一次缓存请求。需要 Codex 0.165 或更新版本；Claude 会话重启后生效。":
    "Claude 또는 Codex 회전 후 빈 컴포터에서 예상되는 다음 메시지를 표시합니다. 탭은 사용합니다. 각각 계획에 추가로 캐시 요청입니다. 필요 Codex 0.165+. Claude 대화 업데이트 재시작.",
  建议下一条提示词: "다음 곧바로 제안",
