    "디스크로 돌려보내려면; 그것은 멈추고 배경 서비스를 다시 시작합니다.이 환경을 호스팅하는 경우 데스크톱 앱을 먼저 제거하십시오.",
  "EAS 模拟器": "EAS 시뮬레이터",
  "通过此环境在 Expo 云端运行 iOS 模拟器。会话停止前会持续向 Expo 账户计费，因此每个主机都设有并发会话数和运行时长限制。编辑或移除主机会停止其正在运行的会话。":
    "이 환경에서 Expo의 클라우드에서 iOS 시뮬레이터를 실행합니다.Sessions bill the Expo account until they stop, so each host limits how many run and for how long.Editing or removing a host stops its running sessions.",
