    "환경의 서버가 Expo에 로그인하고 대화을 시작합니다. 여기에서 토큰이 없으면 EXPO_TOKEN을 사용하고, 그 후에 로그인을 촉진합니다.",
  "Expo 访问令牌": "EXPO 액세스 토큰",
